pub fn eq(a: []const u8, b: []const u8) bool {
    return std.mem.eql(u8, a, b);
}
pub fn indexOf(values: []const []const u8, value: []const u8) usize {
    for (values, 0..) |name, i| if (eq(name, value)) return i;
